<include file="Public:header"/><style>    ul{        margin-left: 49%;    }    li{        float: left;    }</style><div class="mainbox">    <div id="nav" class="mainnav_title">        <ul>            <a href="{pigcms{:U('Appoint/project_list')}" class="on">项目名称列表</a>            <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Appoint/project_add', array('parentid' => $parentid))}','添加项目名称',480,260,true,false,false,addbtn,'add',true);">添加项目名称</a>            <a href="{pigcms{:U('Appoint/project_city_list')}">项目城市列表</a>            <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Appoint/project_city_add', array('parentid' => $parentid))}','添加项目城市',480,260,true,false,false,addbtn,'add',true);">添加项目城市</a>            <a href="{pigcms{:U('Appoint/project_import')}">项目名称导入</a>        </ul>    </div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Appoint/project_list')}" method="get">                    <input type="hidden" name="c" value="Appoint"/>                    <input type="hidden" name="a" value="project_list"/>                    筛选:                    <font color="#000">所属地区：</font>                    <select name="project_city">                        <option value="">全部城市</option>                        <volist name="project_city_arr" id="vo">                            <option value="{pigcms{$vo['project_city_name']}" <if condition="$_GET['project_city'] eq $vo['project_city_name']">selected</if>>{pigcms{$vo['project_city_name']}</option>                        </volist>                    </select>&nbsp;&nbsp;&nbsp;                    <font color="#000">项目：</font>                    <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <input type="submit" style="margin-right:20px;" value="查询" class="button"/>                    <!--							<a href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出佣金记录</a>-->                </form>            </td>        </tr>    </table>    <form name="myform" id="myform" action="" method="post">        <div class="table-list">            <table width="100%" cellspacing="0">                <colgroup>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col width="180" align="center"/>                </colgroup>                <thead>                <tr>                    <th>编号</th>                    <th>城市</th>                    <th>项目名称</th>                    <th class="textcenter">操作</th>                </tr>                </thead>                <tbody>                <if condition="is_array($project_list)">                    <volist name="project_list['project_list']" id="vo">                        <tr>                            <td>{pigcms{$vo.id}</td>                            <td>{pigcms{$vo.city_name}</td>                            <td>{pigcms{$vo.project_name}</td>                            <td class="textcenter">                                <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Appoint/project_edit',array('id'=>$vo['id']))}','编辑项目信息',480,260,true,false,false,editbtn,'edit',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Appoint/project_del')}">删除</a></td>                            </td>                        </tr>                    </volist>                    <tr><td class="textcenter pagebar" colspan="9">{pigcms{$project_list.pagebar}</td></tr>                    <else/>                    <tr><td class="textcenter red" colspan="9">列表为空！</td></tr>                </if>                </tbody>            </table>        </div>    </form></div><include file="Public:footer"/>